//*****************************************************************************
// State
//*****************************************************************************
InvSlot  rc_inv[INV_SLOTS];
uint16_t rc_eq[SL_COUNT];
uint16_t rc_clothMask;
uint16_t rc_sel = 0xFFFFu;
uint16_t rc_cdStaff, rc_cdStaffMax;
uint16_t rc_cdCons[NUM_CONS];
uint16_t rc_relicMask;
uint16_t rc_relicCnt[5];                   // relics carried, per mini-boss relic (the Relics tab)
uint16_t rc_phylacteryUsed;
uint16_t rc_manaDebt;
uint16_t rc_hpBonus;
uint16_t rc_silence, rc_confuse;
int16_t  rc_fx[FX_COUNT];
uint16_t rc_class;
uint16_t rc_classSeen;
uint16_t rc_ult, rc_ultT;

static int16_t  s_cycPos = -1;                  // where the Up cycle last stopped in the bag

// Loot waiting to be handed out (a mini-boss chest gives three things at once).
static uint16_t s_lootQ[4], s_lootN;
static uint16_t s_lootThen;                     // 1 = open the chest's pick-1-of-3 screen afterwards
static uint16_t s_newItem = I_NONE;             // the item the swap screen is placing

// List screen state
static uint16_t s_screen;                       // INV_BAG / INV_SHOP / INV_SWAP
static uint16_t s_row, s_rows, s_tab;           // selected row, row count, shop tab (0 buy, 1 sell)
static uint16_t s_dirty;                        // 1 = redraw rows + panel
static uint16_t s_msg;                          // index into kMsg
static uint16_t s_confirm;                      // Down pressed once on a bag row: press again to drop
static uint16_t s_vendor;

// Vendor stock: 8 lines per vendor, item id (or RUNE_TAG | rune) and how many are left.
#define RUNE_TAG     0x8000u
#define STOCK_LINES  8
static uint16_t s_stock[2][STOCK_LINES], s_stockQty[2][STOCK_LINES], s_stockBlock[2] = { 0xFFFFu, 0xFFFFu };

static const char *const kMsg[] =
{
    "", "Equipped", "Bound forever", "Bag full", "Need a weapon", "Not enough gold",
    "Bought", "Sold", "No room", "Dropped", "Press again to drop", "Selected", "Can't sell this",
    "Slot is bound", "Sold out"
};
enum { M_NONE, M_EQUIP, M_BOUND, M_FULL, M_NEEDWPN, M_GOLD, M_BOUGHT, M_SOLD, M_NOROOM,
       M_DROPPED, M_CONFIRM, M_SELECTED, M_NOSELL, M_SLOTBOUND, M_SOLDOUT };


//*****************************************************************************
// The effect table: stats + runes + gear + relics, rebuilt after any change.
//*****************************************************************************
bool rc_HasRune(uint16_t r)
{
    uint16_t i, cls = rc_kRune[r].cls;

    if(cls != 0u && cls != rc_class) return false;      // a class rune works only in its class
    for(i = 0; i < RUNE_SLOTS; i++)
        if(rc_rune[i] == r) return true;
    return false;
}


void rc_RecalcFx(void)
{
    uint16_t i, s;
    int16_t  hpMax;

    for(i = 0; i < FX_COUNT; i++) rc_fx[i] = 0;

    for(s = 0; s < ST_COUNT; s++)                       // direct stats (soft-capped levels)
    {
        if(s == ST_HP) rc_fx[FX_HP] += (int16_t)(HP_UNITS_PER_HEART * rc_lvStat[s]);
        else rc_fx[s] += (int16_t)(((uint32_t)rc_kStat[s].step * rc_kSoft[rc_lvStat[s]]) >> 8);
    }

    if(rc_HasRune(RU_HASTE))    rc_fx[FX_MOVE]  += 12;  // general runes with a flat effect
    if(rc_HasRune(RU_FORCE))    rc_fx[FX_DMG]   += 20;
    if(rc_HasRune(RU_SWIFT))    rc_fx[FX_ASPD]  += 15;
    if(rc_HasRune(RU_VITAL))    rc_fx[FX_HP]    += HP_UNITS_PER_HEART;
    if(rc_HasRune(RU_CONSERVE)) rc_fx[FX_COST]  += 25;
    if(rc_HasRune(RU_FORTUNE))  rc_fx[FX_GOLD]  += 25;
    if(rc_HasRune(RU_HERMIT))   rc_fx[FX_REGEN] += 50;

    for(s = SL_BODY; s <= SL_ACC; s++)                  // every equipped piece gives its own effect
    {
        uint16_t it = rc_eq[s];
        if(it < I_COUNT && rc_kItems[it].kind == K_GEAR) rc_fx[rc_kItems[it].fx] += (int16_t)rc_kItems[it].val;
    }

    rc_relicMask = 0;                                   // relics work while carried (duplicates do not stack)
    for(i = 0; i < 5u; i++)
        if(rc_relicCnt[i]) rc_relicMask |= (uint16_t)(1u << i);

    hpMax = (int16_t)(HP_START + rc_fx[FX_HP] + (int16_t)rc_hpBonus);
    if(hpMax > HP_CAP) hpMax = HP_CAP;
    if(hpMax < HP_UNITS_PER_HEART) hpMax = HP_UNITS_PER_HEART;
    rc_maxHp = (uint16_t)hpMax;
    if(rc_hp > rc_maxHp) rc_hp = rc_maxHp;
    if(rc_mana > rc_ManaMax()) rc_mana = rc_ManaMax();
    rc_manaShown = -1;
    rc_hud |= HUD_ALL;
}


uint16_t rc_ManaMax(void)
{
    int16_t m = (int16_t)(MANA_BASE + rc_fx[FX_MANA] - (int16_t)rc_manaDebt);
    return (m < 20) ? 20u : (uint16_t)m;
}


uint16_t rc_MaxHpCap(void)
{
    return HP_CAP;
}


//*****************************************************************************
// Classes: Body + Helmet + Accessory of one class activate it. Each bound
// Mimic Cloth counts as a class item for EVERY class, so two cloths plus one
// Pyromancer piece make a Pyromancer; a cloth with pieces of two different
// classes makes no class. (Three cloths end the run when the third binds.)
//*****************************************************************************
static uint16_t ClassFromGear(void)
{
    uint16_t s, c = CL_NONE;

    for(s = SL_BODY; s <= SL_ACC; s++)
    {
        uint16_t it = rc_eq[s];

        if(rc_clothMask & (1u << s)) continue;          // wildcard
        if(it >= I_COUNT || rc_kItems[it].cls == CL_NONE) return CL_NONE;
        if(c == CL_NONE) c = rc_kItems[it].cls;
        else if(c != rc_kItems[it].cls) return CL_NONE; // mixed classes
    }
    return c;                                           // CL_NONE when all three are cloths
}


void rc_UpdateClass(void)
{
    uint16_t c = ClassFromGear();

    if(c == rc_class) return;
    rc_class = c;
    rc_ult = 0;
    rc_ultT = 0;
    rc_hud |= HUD_ULT;
    if(c != CL_NONE)
    {
        rc_Toast("You are now a ", rc_ClassName(c));
        if(!(rc_classSeen & (1u << c)))                  // first activation: the class staff
        {
            uint16_t old = rc_eq[SL_WPN];

            rc_classSeen |= (uint16_t)(1u << c);
            rc_eq[SL_WPN] = (uint16_t)(I_INFERNAL + c - 1u);
            rc_sel = 0xFFFFu;
            if(old < I_COUNT) rc_QueueLoot(old);         // the old staff goes to the bag (swap screen if full)
        }
        rc_Sfx(&sfx_level_up);
    }
    rc_RecalcFx();                                      // class runes switch on / off
    rc_wLoaded = 0xFFFFu;
}


//*****************************************************************************
// Bag helpers
//*****************************************************************************
bool rc_Owns(uint16_t item)
{
    uint16_t i;

    for(i = 0; i < SL_COUNT; i++)  if(rc_eq[i] == item) return true;
    for(i = 0; i < INV_SLOTS; i++) if(rc_inv[i].item == item) return true;
    return false;
}


static int16_t FreeSlot(void)
{
    uint16_t i;

    for(i = 0; i < INV_SLOTS; i++) if(rc_inv[i].item == I_NONE) return (int16_t)i;
    return -1;
}


static void ClearSlot(uint16_t i)
{
    rc_inv[i].item = I_NONE;
    rc_inv[i].cnt  = 0;
    if(rc_sel == i) rc_sel = 0xFFFFu;
}


// Put an item in the bag or wear it. Consumables stack to 3, at most 3 types.
uint16_t rc_GiveItem(uint16_t item)
{
    const ItemDef *d = &rc_kItems[item];
    uint16_t i, types = 0;
    int16_t  f;

    if(d->kind == K_CONS)
    {
        for(i = 0; i < INV_SLOTS; i++)
        {
            if(rc_inv[i].item >= I_FIRST_CONS && rc_inv[i].item < I_FIRST_GEAR) types++;
            if(rc_inv[i].item == item && rc_inv[i].cnt < CONS_STACK) { rc_inv[i].cnt++; return GIVE_OK; }
        }
        f = FreeSlot();
        if(types >= CONS_TYPES || f < 0) return GIVE_NOROOM;
        rc_inv[f].item = item;
        rc_inv[f].cnt  = 1;
        return GIVE_OK;
    }

    if(d->kind == K_RELIC)                              // relics live on their own tab, never in the bag
    {
        if(rc_relicCnt[item - I_FIRST_RELIC] < 9u) rc_relicCnt[item - I_FIRST_RELIC]++;
        rc_RecalcFx();
        return GIVE_OK;
    }

    if(d->kind == K_GEAR && rc_eq[d->slot] == I_NONE && !(rc_clothMask & (1u << d->slot)))
    {
        rc_eq[d->slot] = item;                          // an empty slot equips it straight away
        rc_UpdateClass();
        rc_RecalcFx();
        return GIVE_EQUIPPED;
    }

    f = FreeSlot();
    if(f < 0) return GIVE_FULL;
    rc_inv[f].item = item;
    rc_inv[f].cnt  = 1;
    rc_RecalcFx();                                      // a relic counts as soon as it is carried
    return GIVE_OK;
}


uint16_t rc_SellValue(uint16_t item)
{
    return (uint16_t)((rc_kItems[item].price + 9u) / 10u);   // 10%, rounded up
}


//*****************************************************************************
// Loot hand-out: each item is equipped, bagged, or offered on the swap screen.
//*****************************************************************************
static void BackToPlay(void)
{
    rc_mode      = MODE_PLAY;
    rc_dirtyFull = true;
}


static void LootRun(void)
{
    while(s_lootN)
    {
        uint16_t it = s_lootQ[0], i;

        for(i = 1; i < s_lootN; i++) s_lootQ[i - 1u] = s_lootQ[i];
        s_lootN--;
        if(rc_GiveItem(it) == GIVE_FULL)
        {
            s_newItem = it;
            rc_EnterInventory(INV_SWAP);
            return;
        }
        rc_Toast("Got: ", rc_ItemName(it));
    }
    if(s_lootThen) { s_lootThen = 0; rc_EnterCards(CS_CHEST); }             // the boss chest's pick-1-of-3
    else if(rc_mode == MODE_INV && s_screen == INV_SWAP) BackToPlay();      // the swap screen is done
}


void rc_QueueLoot(uint16_t item)
{
    if(s_lootN < 4u) s_lootQ[s_lootN++] = item;
    if(!(rc_mode == MODE_INV && s_screen == INV_SWAP)) LootRun();          // (the swap screen runs the rest)
}


bool rc_LootPending(void)
{
    return s_lootN != 0u;
}


// Mini-boss package (rc.md 14.2): relic + general piece + class piece now, then pick 1 of 3.
void rc_GiveBossPackage(uint16_t relic, uint16_t general, uint16_t clsItem)
{
    s_lootN = 0;
    s_lootThen = 1;
    if(relic   != I_NONE) s_lootQ[s_lootN++] = relic;
    if(general != I_NONE) s_lootQ[s_lootN++] = general;
    if(clsItem != I_NONE) s_lootQ[s_lootN++] = clsItem;
    LootRun();
}


//*****************************************************************************
// The Up cycle (rc.md 2.2 + the player's controls): Up steps through the weapon
// and every staff / consumable in the bag. Picking a bag staff swaps it into
// the Weapon slot; picking a consumable selects it (Down then uses it).
//*****************************************************************************
uint16_t rc_SelItem(void)
{
    return (rc_sel == 0xFFFFu) ? rc_eq[SL_WPN] : rc_inv[rc_sel].item;
}


void rc_CycleSelection(void)
{
    int16_t i;

    for(i = (int16_t)(s_cycPos + 1); i < INV_SLOTS; i++)
    {
        uint16_t it = rc_inv[i].item;

        if(it >= I_FIRST_GEAR) continue;                // gear, relics, empty: skipped
        if(it < NUM_STAFFS)                             // a staff: swap it into the hand
        {
            rc_inv[i].item = rc_eq[SL_WPN];
            rc_eq[SL_WPN]  = it;
            rc_sel = 0xFFFFu;
            rc_cdStaff = 0;
        }
        else rc_sel = (uint16_t)i;                      // a consumable: select it
        s_cycPos = i;
        break;
    }
    if(i >= INV_SLOTS) { rc_sel = 0xFFFFu; s_cycPos = -1; }  // wrapped: back to the weapon
    rc_hud |= HUD_STAFF;
    rc_viewDirty = 2;
    rc_Sfx(&sfx_menu_move);
}


// After a consumable is used: one less in the stack.
void rc_SpendSelected(void)
{
    if(rc_sel == 0xFFFFu) return;
    if(--rc_inv[rc_sel].cnt == 0u) { ClearSlot(rc_sel); s_cycPos = -1; }
    rc_hud |= HUD_STAFF;
}


//*****************************************************************************
// Vendors (rc.md 11): 8 lines - Elixirs x2, Mana Potions x2, then 6 random
// pieces (gear, class gear, generic staffs, consumables, sometimes a rune).
// Restocked every three waves. Class items and staffs you own are not offered.
//*****************************************************************************
static uint16_t RandomShopItem(void)
{
    uint16_t k, tries;

    for(tries = 0; tries < 20u; tries++)
    {
        k = RAND(10);
        if(k == 0u) return (uint16_t)(RUNE_TAG | RAND(RU_GENERAL));                     // 10% a rune
        if(k <= 2u) { uint16_t c = (uint16_t)(I_FIRST_CONS + RAND(NUM_CONS - 1u)); if(c != I_ELIXIR) return c; continue; }
        if(k <= 5u) return (uint16_t)(I_FIRST_GEAR + RAND(12));                         // general gear
        if(k <= 8u) { uint16_t c = (uint16_t)(I_CLASS0 + RAND(33)); if(!rc_Owns(c)) return c; continue; }
        { uint16_t st = (uint16_t)(I_PRISM + RAND(3)); if(!rc_Owns(st)) return st; }   // generic staff
    }
    return I_MANAPOT;
}


static void Restock(uint16_t v)
{
    uint16_t block = (uint16_t)((rc_wave - 1u) / 3u), i, k;

    if(s_stockBlock[v] == block) return;
    s_stockBlock[v] = block;
    s_stock[v][0] = I_ELIXIR;   s_stockQty[v][0] = 2;
    s_stock[v][1] = I_MANAPOT;  s_stockQty[v][1] = 2;
    for(i = 2; i < STOCK_LINES; i++)
    {
        uint16_t it;
        do { it = RandomShopItem(); for(k = 2; k < i && s_stock[v][k] != it; k++) {} } while(k < i);   // no repeats
        s_stock[v][i] = it;
        s_stockQty[v][i] = 1;
    }
}


static uint16_t StockPrice(uint16_t s)
{
    return (s & RUNE_TAG) ? RUNE_PRICE : rc_kItems[s].price;
}


//*****************************************************************************
// Screens. The inventory is a grid in the style of a block-building game:
// equipment on the left, a 6 x 2 bag, and tabs for Items / Runes / Relics,
// every item drawn as a 2x icon. The vendor (buy / sell) and the full-bag swap
// screen use the same cells, 8 to a row (LIST_COLS), with the details underneath.
//*****************************************************************************
#define CELL        38                  // grid cell pitch (a 32 px icon + border)
#define LIST_X      8                   // vendor / swap grid
#define LIST_COLS   8
#define EQ_X        8                   // equipment column
#define GRID_X      56                  // bag grid / rune row / relic row
#define GRID_Y      28
#define GPANEL_Y    106                 // details panel under the grid
enum { TAB_ITEMS, TAB_RUNES, TAB_RELICS };

static uint16_t s_cx, s_cy;             // grid cursor (column 0 = equipment on the Items tab)
static uint16_t s_lastCell = 0xFFFFu;   // cell drawn as selected last time

// Colour of each class's gear (and runes); index 0 = general gear (steel).
static const uint32_t kClassRgb[CL_COUNT] =
    { 0x00A8B0BCUL, 0x00E05020UL, 0x00F0D030UL, 0x0060D060UL, 0x0070A0FFUL, 0x00A050D0UL, 0x00FFC020UL };
static const uint32_t kRelicRgb[5] = { 0x00D03030UL, 0x0040C040UL, 0x0040FF80UL, 0x00FF8020UL, 0x00B01030UL };


void rc_EnterInventory(uint16_t screen)
{
    if(screen == INV_SHOP)
    {
        s_vendor = (rc_prop[rc_iaIdx].room == RM_EC) ? 1u : 0u;
        Restock(s_vendor);
    }
    s_tab      = 0;
    s_screen   = screen;
    s_row      = 0;
    s_cx = s_cy = 0;
    s_msg      = M_NONE;
    s_confirm  = 0;
    rc_mode    = MODE_INV;
    rc_dirtyFull = true;
    rc_stX = rc_stY = 1;
}


static void RowCount(void)
{
    if(s_screen == INV_BAG)       s_rows = SL_COUNT + INV_SLOTS;
    else if(s_screen == INV_SWAP) s_rows = INV_SLOTS;
    else                          s_rows = s_tab ? (uint16_t)(INV_SLOTS + 5u) : STOCK_LINES;   // sell: bag + relics
}


// What row r shows: an item id (or a rune for shop lines), and a count / price.
static uint16_t RowItem(uint16_t r, uint16_t *qty)
{
    *qty = 0;
    if(s_screen == INV_SHOP && !s_tab) { *qty = s_stockQty[s_vendor][r]; return s_stock[s_vendor][r]; }
    if(s_screen == INV_SHOP && r >= INV_SLOTS)                              // relic rows of the sell list
    {
        *qty = rc_relicCnt[r - INV_SLOTS];
        return *qty ? (uint16_t)(I_FIRST_RELIC + r - INV_SLOTS) : I_NONE;
    }
    if(s_screen == INV_BAG)
    {
        if(r < SL_COUNT) return rc_eq[r];
        r = (uint16_t)(r - SL_COUNT);
    }
    *qty = rc_inv[r].cnt;
    return rc_inv[r].item;
}


// The item under the grid cursor (runes come back as RUNE_TAG | rune).
static uint16_t GridItem(uint16_t *qty)
{
    *qty = 0;
    if(s_tab == TAB_RUNES)  return (rc_rune[s_cx] == RUNE_NONE) ? I_NONE : (uint16_t)(RUNE_TAG | rc_rune[s_cx]);
    if(s_tab == TAB_RELICS) { *qty = rc_relicCnt[s_cx]; return *qty ? (uint16_t)(I_FIRST_RELIC + s_cx) : I_NONE; }
    return RowItem(s_row, qty);
}


static const char *ItemName(uint16_t it)
{
    if(it & RUNE_TAG) return rc_RuneName(it & 0xFFu);
    return (it < I_COUNT) ? rc_ItemName(it) : "-";
}


static void LeftText(const char *s, int16_t x, int16_t y, uint32_t fg, uint32_t bg)
{
    int16_t n = 0;

    while(s[n]) n++;
    if(!n) return;
    Graphics_setFont(&g_sContext, &g_sFontCmss12b);
    Graphics_setForegroundColor(&g_sContext, fg);
    Graphics_setBackgroundColor(&g_sContext, bg);
    Graphics_drawString(&g_sContext, (int16_t *)s, n, x, y, OPAQUE_TEXT);
    Graphics_setFont(&g_sContext, &g_sFontCmss20b);
}


//-----------------------------------------------------------------------------
// Icons: a 16 x 16 sprite drawn at 2x, one FillRect per vertical colour run.
//-----------------------------------------------------------------------------
static void DrawIcon(uint16_t shape, int16_t x, int16_t y, const uint32_t *pal)
{
    const uint16_t *art = rc_kArt[shape];
    uint16_t cx, r, r1, px;

    for(cx = 0; cx < SPR_N; cx++)
        for(r = 0; r < SPR_N; r = (uint16_t)(r1 + 1u))
        {
            px = (uint16_t)((art[(r << 2) + (cx >> 2)] >> ((cx & 3u) << 2)) & 15u);
            r1 = r;
            if(!px) continue;
            while(r1 + 1u < SPR_N && ((art[((r1 + 1u) << 2) + (cx >> 2)] >> ((cx & 3u) << 2)) & 15u) == px) r1++;
            Graphics_FillRect((int16_t)(x + 2 * cx), (int16_t)(y + 2 * r), (int16_t)(x + 2 * cx + 1),
                              (int16_t)(y + 2 * r1 + 1), pal[px - 1u]);
        }
}


static uint32_t Shade(uint32_t c) { return (c >> 1) & 0x7F7F7FUL; }

// Pick an icon shape and its colours for an item, rune or relic.
static uint16_t ItemIcon(uint16_t it, uint32_t *p)
{
    static const uint16_t kGearIcon[3] = { SH_ICON_BODY, SH_ICON_HELM, SH_ICON_RING };
    uint32_t main;
    uint16_t i;

    for(i = 0; i < PAL_N; i++) p[i] = COLOR_MAGENTA;
    p[0] = 0x00101010UL; p[3] = COLOR_WHITE;                // a outline, d highlight
    if(it & RUNE_TAG)                                       // rune stone: glyph in the class colour
    {
        p[1] = rc_kRune[it & 0xFFu].cls ? kClassRgb[rc_kRune[it & 0xFFu].cls] : COLOR_VIOLET;
        p[2] = 0x00707078UL;
        return SH_ICON_RUNE;
    }
    switch(rc_kItems[it].kind)
    {
        case K_STAFF: p[1] = rc_kStaffs[it].color; p[2] = 0x007A5030UL; return SH_ICON_STAFF;
        case K_CONS:                                         // flask: a liquid, b glass rim, c glass, d cork
            p[0] = rc_kWpnPal[rc_kItems[it].pal][8]; p[1] = 0x00101010UL; p[2] = COLOR_LIGHT_GRAY; p[3] = COLOR_BROWN;
            return SH_FLASK;
        case K_RELIC:                                        // glowing orb
            main = kRelicRgb[it - I_FIRST_RELIC];
            p[0] = Shade(main); p[1] = main; p[2] = main | 0x00404040UL;
            return SH_ORB;
        case K_CLOTH:
            for(i = 0; i < PAL_N; i++) p[i] = rc_kPal[PT_MIMIC][i];
            return SH_MIMIC;
        default:                                             // gear: class colour (steel if general)
            main = kClassRgb[rc_kItems[it].cls];
            p[1] = main; p[2] = Shade(main); p[3] = 0x00FFE080UL;
            return kGearIcon[rc_kItems[it].slot];
    }
}


// Cell number c on the current tab: its screen position and contents.
static void CellPos(uint16_t c, int16_t *x, int16_t *y)
{
    if(s_screen != INV_BAG)
    {
        *x = (int16_t)(LIST_X + CELL * (c % LIST_COLS));
        *y = (int16_t)(GRID_Y + CELL * (c / LIST_COLS));
        return;
    }
    if(s_tab == TAB_ITEMS && c < SL_COUNT) { *x = EQ_X; *y = (int16_t)(GRID_Y + CELL * c); return; }
    if(s_tab == TAB_ITEMS) c = (uint16_t)(c - SL_COUNT);
    *x = (int16_t)(GRID_X + CELL * (c % 6u));
    *y = (int16_t)(GRID_Y + CELL * (c / 6u));
}


static uint16_t CellCount(void)
{
    if(s_screen != INV_BAG) return s_rows;
    return (s_tab == TAB_ITEMS) ? (uint16_t)(SL_COUNT + INV_SLOTS) : (s_tab == TAB_RUNES) ? RUNE_SLOTS : 5u;
}


static uint16_t CurCell(void)
{
    if(s_screen != INV_BAG) return s_row;
    if(s_tab != TAB_ITEMS) return s_cx;
    return (s_cx == 0u) ? s_cy : (uint16_t)(SL_COUNT + s_cy * 6u + s_cx - 1u);
}


static void DrawCell(uint16_t c)
{
    int16_t  x, y;
    uint16_t it, qty = 0, sh;
    uint32_t pal[PAL_N];
    bool     sel = (c == CurCell());
    char     buf[6];

    CellPos(c, &x, &y);
    Graphics_FillRect(x, y, (int16_t)(x + 35), (int16_t)(y + 35), sel ? C_CYAN : COLOR_CHARCOAL);
    Graphics_FillRect((int16_t)(x + 2), (int16_t)(y + 2), (int16_t)(x + 33), (int16_t)(y + 33), sel ? 0x00303848UL : 0x00181C22UL);

    if(s_screen != INV_BAG)                 { it = RowItem(c, &qty); if(s_screen == INV_SHOP && !s_tab) qty = qty ? 0u : 0xFFFFu; }
    else if(s_tab == TAB_ITEMS && c < SL_COUNT) it = rc_eq[c];
    else if(s_tab == TAB_ITEMS)            { it = rc_inv[c - SL_COUNT].item; qty = rc_inv[c - SL_COUNT].cnt; }
    else if(s_tab == TAB_RUNES)            it = (rc_rune[c] == RUNE_NONE) ? I_NONE : (uint16_t)(RUNE_TAG | rc_rune[c]);
    else                        { qty = rc_relicCnt[c]; it = qty ? (uint16_t)(I_FIRST_RELIC + c) : I_NONE; }

    if(qty == 0xFFFFu)                                          // vendor line sold out
    {
        rc_DrawSmall("SOLD", (int16_t)(x + 18), (int16_t)(y + 18), C_DKGRAY, sel ? 0x00303848UL : 0x00181C22UL);
        return;
    }
    if(it == I_NONE)
    {
        if(s_screen == INV_BAG && s_tab == TAB_ITEMS && c < SL_COUNT)                  // empty equipment slot: a dim outline of what goes there
        {
            static const uint16_t kSlotIcon[SL_COUNT] = { SH_ICON_BODY, SH_ICON_HELM, SH_ICON_RING, SH_ICON_STAFF };
            uint16_t i;
            for(i = 0; i < PAL_N; i++) pal[i] = 0x00282C34UL;
            DrawIcon(kSlotIcon[c], (int16_t)(x + 2), (int16_t)(y + 2), pal);
        }
        return;
    }
    sh = ItemIcon(it, pal);
    DrawIcon(sh, (int16_t)(x + 2), (int16_t)(y + 2), pal);
    if(qty > 1u) { rc_Itoa(buf, qty); LeftText(buf, (int16_t)(x + 26), (int16_t)(y + 22), C_WHITE, 0x00181C22UL); }
    if(s_screen == INV_SHOP && !s_tab && rc_gold < StockPrice(it))
        Graphics_FillRect((int16_t)(x + 2), (int16_t)(y + 31), (int16_t)(x + 33), (int16_t)(y + 33), C_BAD);   // can't afford
    if(s_screen == INV_BAG && s_tab == TAB_ITEMS && c < SL_COUNT && (rc_clothMask & (1u << c)))
        Graphics_FillRect((int16_t)(x + 2), (int16_t)(y + 31), (int16_t)(x + 33), (int16_t)(y + 33), C_BAD);   // bound forever
}


// Details of the selected thing: name, description, class, value, and any message.
static void DrawPanel(void)
{
    bool     bag = (s_screen == INV_BAG);
    uint16_t qty, it = bag ? GridItem(&qty) : RowItem(s_row, &qty);
    int16_t  px = bag ? GRID_X : LIST_X, n,
             y  = bag ? GPANEL_Y : (int16_t)(GRID_Y + CELL * ((s_rows + LIST_COLS - 1u) / LIST_COLS) + 4);
    char     buf[28];

    Graphics_FillRect(px, (int16_t)(y - 2), SCREEN_W - 1, 224, C_BLACK);
    if(bag)
    {
        n = rc_Cat(buf, 0, "Class: ", 7);
        rc_Cat(buf, n, rc_ClassName(rc_class), 12);
        LeftText(buf, px, y, rc_class ? C_XP : C_GRAY, C_BLACK);
        y = (int16_t)(y + 18);
    }
    if(it != I_NONE)
    {
        const char *d = (it & RUNE_TAG) ? rc_RuneDesc(it & 0xFFu) : rc_ItemDesc(it);
        char     line[16];
        uint16_t k, m = 0;

        LeftText(ItemName(it), px, y, C_WHITE, C_BLACK);
        y = (int16_t)(y + 15);
        for(k = 0; ; k++)                                   // description lines
        {
            if(d[k] == '|' || d[k] == 0)
            {
                line[m] = 0;
                LeftText(line, px, y, C_GRAY, C_BLACK);
                y = (int16_t)(y + 13);
                m = 0;
                if(!d[k]) break;
            }
            else if(m < 15u) line[m++] = d[k];
        }
        if(!(it & RUNE_TAG) && rc_kItems[it].cls)
        {
            LeftText(rc_ClassName(rc_kItems[it].cls), px, y, C_XP, C_BLACK);
            y = (int16_t)(y + 13);
        }
        if(s_screen == INV_SHOP && !s_tab)                  // the vendor's price
        {
            uint16_t pr = StockPrice(it);
            n = rc_Cat(buf, 0, "Price ", 6);
            n += rc_Itoa(buf + n, pr);
            rc_Cat(buf, n, "g", 1);
            LeftText(buf, px, y, (rc_gold >= pr) ? C_GOLD : C_BAD, C_BLACK);
        }
        else if(!(it & RUNE_TAG))
        {
            n = rc_Cat(buf, 0, "Sells for ", 10);
            n += rc_Itoa(buf + n, rc_SellValue(it));
            rc_Cat(buf, n, "g", 1);
            LeftText(buf, px, y, C_GOLD, C_BLACK);
        }
    }
    if(s_msg) LeftText(kMsg[s_msg], 210, 210,
                       (s_msg == M_BOUGHT || s_msg == M_SOLD || s_msg == M_EQUIP) ? C_GREEN : C_BAD, C_BLACK);
}


void rc_DrawInventoryFull(void)
{
    char    buf[28];
    int16_t n;

    Graphics_FillRect(0, 0, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);
    RowCount();
    if(s_screen == INV_BAG)                             // tabs
    {
        static const char *const kTab[3] = { "ITEMS", "RUNES", "RELICS" };
        static const UiHint k[] = { { UI_ICON_L, "" }, { UI_ICON_R, "Tab" }, { UI_ICON_STICK_CLICK, "Use" },
                                    { UI_ICON_D, "Drop" }, { UI_ICON_U, "Close" } };
        uint16_t t;

        for(t = 0; t < 3u; t++)
        {
            int16_t x0 = (int16_t)(8 + 78 * t);
            Graphics_FillRect(x0, 4, (int16_t)(x0 + 72), 22, (t == s_tab) ? C_GOLD : COLOR_CHARCOAL);
            rc_DrawTextEx(kTab[t], (int16_t)(x0 + 36), 13, (t == s_tab) ? C_BLACK : C_GRAY,
                          (t == s_tab) ? C_GOLD : COLOR_CHARCOAL, true);
        }
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 231, C_BLACK);
    }
    else if(s_screen == INV_SWAP)
    {
        static const UiHint k[] = { { UI_ICON_STICK_CLICK, "Replace" }, { UI_ICON_U, "Throw new away" } };
        n = rc_Cat(buf, 0, "Bag full: ", 10);
        rc_Cat(buf, n, rc_ItemName(s_newItem), 16);
        rc_DrawText(buf, 120, 13, C_BAD);
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 231, C_BLACK);
    }
    else
    {
        static const UiHint k[] = { { UI_ICON_L, "" }, { UI_ICON_R, "Buy/Sell" },
                                    { UI_ICON_STICK_CLICK, "Trade" }, { UI_ICON_U, "Leave" } };
        rc_DrawText(s_tab ? "VENDOR - SELL" : "VENDOR - BUY", 90, 13, C_GOLD);
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 231, C_BLACK);
    }

    n = rc_Cat(buf, 0, "G ", 2);
    rc_Itoa(buf + n, rc_gold);
    rc_DrawSmall(buf, 290, 13, C_GOLD, C_BLACK);
    s_lastCell = 0xFFFFu;
    s_dirty = 2;                                        // 2 = everything, 1 = the selection changed
}


void rc_InventoryRender(void)
{
    uint16_t r;

    if(!s_dirty) return;
    RowCount();
    if(s_dirty == 2u || s_lastCell == 0xFFFFu) { for(r = 0; r < CellCount(); r++) DrawCell(r); }
    else { DrawCell(s_lastCell); DrawCell(CurCell()); }
    s_lastCell = CurCell();
    DrawPanel();
    s_dirty = 0;
}


//-----------------------------------------------------------------------------
// Actions
//-----------------------------------------------------------------------------
static void BagAction(void)
{
    uint16_t qty, it = RowItem(s_row, &qty);

    s_confirm = 0;
    if(s_row < SL_COUNT)                                // an equipment slot: take it off
    {
        int16_t f;

        if(rc_clothMask & (1u << s_row)) { s_msg = M_BOUND; return; }
        if(s_row == SL_WPN || it == I_NONE) { s_msg = M_NEEDWPN * (s_row == SL_WPN); return; }
        f = FreeSlot();
        if(f < 0) { s_msg = M_FULL; return; }
        rc_inv[f].item = it; rc_inv[f].cnt = 1;
        rc_eq[s_row] = I_NONE;
    }
    else
    {
        uint16_t b = (uint16_t)(s_row - SL_COUNT), k;

        if(it == I_NONE) return;
        k = rc_kItems[it].kind;
        if(k == K_CONS) { rc_sel = b; s_cycPos = (int16_t)b; s_msg = M_SELECTED; rc_hud |= HUD_STAFF; return; }
        if(k == K_RELIC) return;
        k = (k == K_STAFF) ? SL_WPN : rc_kItems[it].slot;
        if(rc_clothMask & (1u << k)) { s_msg = M_SLOTBOUND; return; }
        rc_inv[b].item = rc_eq[k];                      // swap with what was worn (may be empty)
        rc_inv[b].cnt  = (rc_eq[k] == I_NONE) ? 0u : 1u;
        rc_eq[k] = it;
        if(k == SL_WPN) { rc_sel = 0xFFFFu; rc_cdStaff = 0; }
        s_msg = M_EQUIP;
    }
    rc_UpdateClass();
    rc_RecalcFx();
    rc_wLoaded = 0xFFFFu;
    rc_Sfx(&sfx_menu_select);
}


static void ShopAction(void)
{
    uint16_t qty, it = RowItem(s_row, &qty);

    if(it == I_NONE) return;
    if(s_tab)                                           // sell from the bag or the relics (worn gear can't be sold)
    {
        uint16_t b = s_row, v = rc_SellValue(it);

        if(rc_kItems[it].kind == K_CLOTH) { s_msg = M_NOSELL; return; }
        rc_gold = (uint16_t)(rc_gold + v);
        if(b >= INV_SLOTS) rc_relicCnt[b - INV_SLOTS]--;
        else if(--rc_inv[b].cnt == 0u) ClearSlot(b);
        rc_RecalcFx();
        s_msg = M_SOLD;
        rc_Sfx(&sfx_coin);
        return;
    }
    if(qty == 0u) { s_msg = M_SOLDOUT; return; }
    if(rc_gold < StockPrice(it)) { s_msg = M_GOLD; rc_Sfx(&sfx_menu_bump); return; }
    if(it & RUNE_TAG)
    {
        rc_gold -= RUNE_PRICE;
        s_stockQty[s_vendor][s_row]--;
        rc_OfferRune((uint16_t)(it & 0xFFu));           // equips it, or asks which rune to replace
        return;
    }
    {
        uint16_t r = rc_GiveItem(it);

        if(r == GIVE_FULL || r == GIVE_NOROOM) { s_msg = M_NOROOM; rc_Sfx(&sfx_menu_bump); return; }
    }
    rc_gold -= rc_kItems[it].price;
    s_stockQty[s_vendor][s_row]--;
    s_msg = M_BOUGHT;
    rc_Sfx(&sfx_coin);
}


// Swap screen: the chosen bag item is thrown away and the new item takes its place.
static void SwapAction(bool throwNew)
{
    if(!throwNew)
    {
        rc_inv[s_row].item = s_newItem;
        rc_inv[s_row].cnt  = 1;
        if(rc_sel == s_row) rc_sel = 0xFFFFu;
        rc_RecalcFx();
        rc_Toast("Got: ", rc_ItemName(s_newItem));
    }
    s_newItem = I_NONE;
    rc_Sfx(&sfx_menu_select);
    LootRun();                                          // next loot, the chest screen, or back to play
    if(rc_mode == MODE_INV && s_screen == INV_SWAP) rc_dirtyFull = true;
}


void rc_UpdateInventory(void)
{
    int16_t  sy = rc_StickEdge(g_joy.dy, &rc_stY);
    uint16_t old = s_row;

    RowCount();

    if(g_dpad.uPressed)                                 // Up: close / leave / throw the new item away
    {
        rc_Sfx(&sfx_menu_back);
        if(s_screen == INV_SWAP) SwapAction(true);
        else BackToPlay();
        return;
    }
    if(g_dpad.lPressed || g_dpad.rPressed)              // L / R: the vendor's Buy / Sell, the bag's tabs
    {
        if(s_screen == INV_SHOP) s_tab ^= 1u;
        else if(s_screen == INV_BAG) s_tab = (uint16_t)((s_tab + (g_dpad.rPressed ? 1u : 2u)) % 3u);
        else return;
        s_row = 0;
        s_cx = s_cy = 0;
        s_msg = M_NONE;
        rc_dirtyFull = true;
        return;
    }

    if(s_screen == INV_BAG)                             // grid cursor: equipment column, then a 6 x 2 bag
    {
        int16_t sx = rc_StickEdge(g_joy.dx, &rc_stX);
        uint16_t maxX = (s_tab == TAB_ITEMS) ? 6u : (uint16_t)(CellCount() - 1u);
        uint16_t ocx = s_cx, ocy = s_cy;

        if(sx > 0 && s_cx < maxX) s_cx++;
        if(sx < 0 && s_cx > 0u)   s_cx--;
        if(s_tab == TAB_ITEMS)
        {
            uint16_t maxY = s_cx ? 1u : 3u;
            if(sy > 0 && s_cy < maxY) s_cy++;
            if(sy < 0 && s_cy > 0u)   s_cy--;
            if(s_cy > maxY) s_cy = maxY;
            s_row = (s_cx == 0u) ? s_cy : (uint16_t)(SL_COUNT + s_cy * 6u + s_cx - 1u);
        }
        if(s_cx != ocx || s_cy != ocy) { s_confirm = 0; s_msg = M_NONE; if(!s_dirty) s_dirty = 1; rc_Sfx(&sfx_menu_move); }
        if(s_tab != TAB_ITEMS) return;                  // runes and relics: look only
    }
    else
    {
        int16_t sx = rc_StickEdge(g_joy.dx, &rc_stX);

        if(sx > 0 || g_dpad.dPressed) s_row = (uint16_t)((s_row + 1u) % s_rows);
        else if(sx < 0) s_row = (uint16_t)((s_row + s_rows - 1u) % s_rows);
        else if(sy > 0 && s_row + LIST_COLS < s_rows) s_row = (uint16_t)(s_row + LIST_COLS);
        else if(sy < 0 && s_row >= LIST_COLS)         s_row = (uint16_t)(s_row - LIST_COLS);
        if(s_row != old) { s_confirm = 0; s_msg = M_NONE; if(!s_dirty) s_dirty = 1; rc_Sfx(&sfx_menu_move); }
    }

    if(s_screen == INV_BAG && g_dpad.dPressed && s_row >= SL_COUNT)     // Down twice: drop the item
    {
        uint16_t b = (uint16_t)(s_row - SL_COUNT);

        if(rc_inv[b].item != I_NONE)
        {
            if(!s_confirm) { s_confirm = 1; s_msg = M_CONFIRM; }
            else           { ClearSlot(b); rc_RecalcFx(); s_confirm = 0; s_msg = M_DROPPED; }
            s_dirty = 2;
        }
    }

    if(g_joy.btnPressed)
    {
        if(s_screen == INV_BAG)       BagAction();
        else if(s_screen == INV_SHOP) ShopAction();
        else                          { SwapAction(false); return; }
        if(rc_mode == MODE_INV) { rc_dirtyFull = (s_screen == INV_SHOP); s_dirty = 2; }     // (gold changed)
    }
}


//*****************************************************************************
// Run reset
//*****************************************************************************
void rc_ResetInventory(void)
{
    uint16_t i;

    for(i = 0; i < INV_SLOTS; i++) { rc_inv[i].item = I_NONE; rc_inv[i].cnt = 0; }
    for(i = 0; i < SL_COUNT; i++) rc_eq[i] = I_NONE;
    for(i = 0; i < NUM_CONS; i++) rc_cdCons[i] = 0;
    for(i = 0; i < 5u; i++) rc_relicCnt[i] = 0;
    rc_eq[SL_WPN] = I_RAYWAND;
    rc_clothMask = 0;
    rc_sel = 0xFFFFu;
    s_cycPos = -1;
    rc_cdStaff = rc_cdStaffMax = 0;
    rc_phylacteryUsed = 0;
    rc_manaDebt = 0;
    rc_hpBonus = 0;
    rc_silence = rc_confuse = 0;
    rc_class = CL_NONE;
    rc_classSeen = 0;
    rc_ult = rc_ultT = 0;
    s_lootN = 0;
    s_lootThen = 0;
    s_stockBlock[0] = s_stockBlock[1] = 0xFFFFu;
    rc_RecalcFx();
}
